import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def person(last, first):
    return Student("id", last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_sorted_rows(self):
        found = seating_rows(
            [
                person("Halloway", "Juno"),
                person("Zane", "Ola"),
                person("Dunmere", "Piet")
            ],
            2
        )
        self.assertEqual(
            found,
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Zane, Ola"
            ]
        )

    def test_bad_seats(self):
        for seats in (0, -1):
            with self.assertRaises(ProjectError):
                seating_rows([person("Zane", "Ola")], seats)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 2)
